import heapq


def _build_quota(capacity, tie):
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best = None
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best is None or value > best_value or
                    (value == best_value and
                     ((selected > best_ids) if tie == "largest" else (selected < best_ids)))):
                best, best_value, best_ids = subset, value, selected
        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_ledger():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator * 2 + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        descending = sorted(names, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, []))
            choices.append([None] + [v for v in versions
                                     if name not in pins or pins[name] == v])

        best_vector = None
        best = None
        for values in product(*choices):
            selected = dict(zip(names, values))
            if any(selected.get(name) is None or
                   not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            rows = {}
            for name, version in selected.items():
                if version is not None:
                    rows[name] = next(row for row in packages[name]
                                      if row["version"] == version)

            edges = {}
            valid = True
            for name, row in rows.items():
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = selected.get(target)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    deps.append(target)
                edges[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            reached = set()
            active = set()
            cyclic = False
            def visit(name):
                nonlocal cyclic
                if name in active:
                    cyclic = True
                    return
                if name in reached:
                    return
                active.add(name)
                for target in edges.get(name, []):
                    visit(target)
                    if cyclic:
                        return
                active.remove(name)
                reached.add(name)
            for name in roots:
                visit(name)
                if cyclic:
                    break
            if cyclic or reached != set(rows):
                continue
            vector = tuple(selected[name] if selected[name] is not None else -1
                           for name in descending)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best = {name: version for name, version in selected.items()
                        if version is not None}
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_routes():
    def solve(data):
        n = data["n"]
        graph = [[] for _ in range(n)]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        coupons = data["coupons"]
        start = data["start"]
        initial = (source, initial_mask, coupons)
        dist = {initial: start}
        queue = [(start, source, initial_mask, coupons)]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, left in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, left)
                    if next_time < dist.get(next_state, float("inf")):
                        dist[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, left))
        return {"arrival": None}
    return solve


